import { useEffect,useMemo,useState } from 'react'; import { Link,Route,Routes,useNavigate,useParams } from 'react-router-dom'; import { Activity,ArrowDownRight,ArrowUpRight,BookOpen,Brain,CalendarDays,Check,ChevronDown,ChevronLeft,ChevronRight,ClipboardCheck,Clock3,Download,Eye,EyeOff,FileText,Flag,HelpCircle,LayoutDashboard,LogOut,Menu,Monitor,Play,Plus,ScanFace,Search,Settings,Shield,ShieldCheck,Users,Video,Wifi, X } from 'lucide-react'; import { Bar,BarChart,CartesianGrid,ResponsiveContainer,Tooltip,XAxis,YAxis } from 'recharts'; import { api,clearSession,saveSession } from './api';
