function readableApiError(err:any,fallback:string){const detail=err?.response?.data?.detail;if(Array.isArray(detail))return detail.map((x:any)=>x.msg||String(x)).join('. ');if(typeof detail==='string')return detail;if(!err?.response)return 'Cannot connect to the local ProctorAI API. Start the backend in a second terminal, then try again.';return fallback}
function PasswordField({value,onChange,placeholder,minLength}:any){const [visible,setVisible]=useState(false);return <div className='password-field'><input type={visible?'text':'password'} required minLength={minLength} value={value} onChange={onChange} placeholder={placeholder}/><button type='button' onClick={()=>setVisible(v=>!v)} aria-label={visible?'Hide password':'Show password'} title={visible?'Hide password':'Show password'}>{visible?<EyeOff size={16}/>:<Eye size={16}/>}</button></div>}
function ProctorAnalyzer(){const [status,setStatus]=useState('Camera analysis starts after your consent');const unavailable=useRef(false),timers=useRef<Record<string,number>>({}),sent=useRef<Record<string,boolean>>({}),cleared=useRef<Record<string,number>>(),lastNotice=useRef(0);if(!cleared.current)cleared.current={};useEffect(()=>{let cancelled=false;const monitor=async()=>{const attemptId=localStorage.getItem('proctorai-attempt');const video=document.querySelector('.camera-view video') as HTMLVideoElement|null;if(!attemptId||!video||video.readyState<2||cancelled||unavailable.current)return;try{const apiTarget=new URL(api.defaults.baseURL||'http://127.0.0.1:8000/api',window.location.href);if(!['localhost','127.0.0.1','::1'].includes(apiTarget.hostname))throw new Error('Camera analysis only permits a local API');const canvas=document.createElement('canvas');canvas.width=320;canvas.height=240;canvas.getContext('2d')?.drawImage(video,0,0,320,240);const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',.65));if(!blob)return;const form=new FormData();form.append('frame',blob,'frame.jpg');const {data}=await api.post('/proctoring/analyze-frame',form);setStatus('Local face analysis is active · one incident snapshot may be stored');const now=Date.now();const candidates:string[]=[];if(data.face_count===0)candidates.push('face_absent');if(data.face_count>1)candidates.push('multiple_faces');if(data.gaze&&data.gaze!=='center')candidates.push('looking_away');if(Math.abs(data.yaw||0)>20||Math.abs(data.pitch||0)>20)candidates.push('head_deviation');const thresholds:Record<string,number>={face_absent:3000,multiple_faces:3000,looking_away:4000,head_deviation:5000};for(const key of ['face_absent','multiple_faces','looking_away','head_deviation']){if(candidates.includes(key)){timers.current[key]??=now;cleared.current![key]=0;if(!sent.current[key]&&now-timers.current[key]>=thresholds[key]&&now-lastNotice.current>5000){sent.current[key]=true;lastNotice.current=now;const {data:notice}=await api.post('/proctoring/events',{attempt_id:Number(attemptId),event_type:key,duration_seconds:Math.round((now-timers.current[key])/1000),details:{source:'local MediaPipe frame analysis',gaze:data.gaze,face_count:data.face_count}});window.dispatchEvent(new CustomEvent('proctor-warning',{detail:notice}));if(notice.terminated){localStorage.removeItem('proctorai-attempt');setStatus('Exam paused for administrator review')}break}}else{cleared.current![key]=(cleared.current![key]||0)+1;if(cleared.current![key]>=3){delete timers.current[key];delete sent.current[key];delete cleared.current![key]}}}}catch(e:any){unavailable.current=true;setStatus(e?.response?.data?.detail||'Local face analysis is unavailable. No signals are being generated; tell your administrator.')}};const id=setInterval(monitor,1800);return()=>{cancelled=true;clearInterval(id)}},[]);return <div className={unavailable.current?'analyzer-status unavailable':'analyzer-status'}><span/> {status}</div>}const demo={admin:{email:'admin@proctorai.example.com',password:'AdminDemo2026!'},student:{email:'student@proctorai.example.com',password:'StudentDemo2026!'}};
function App(){const [user,setUser]=useState<User|null>(()=>{try{return JSON.parse(localStorage.getItem('proctorai-user')||'null')}catch{return null}});const [menu,setMenu]=useState(false);const nav=useNavigate();function logout(){clearSession();setUser(null);nav('/')}return <Routes><Route path="/" element={<Landing/>}/><Route path="/login" element={<Login onLogin={setUser}/>}/><Route path="/register" element={<Register onLogin={setUser}/>}/><Route path="/app/*" element={user?<Shell user={user} logout={logout}/>:<Login onLogin={setUser}/>}/><Route path="*" element={<Landing/>}/></Routes>}
function Landing(){return <div className="landing landing-editorial"><div className="announcement-bar"><span>LOCAL-FIRST</span><p>Online assessment built around student trust</p><a href="#platform">Explore the platform <ArrowUpRight size={13}/></a></div><nav className="topbar"><Link className="brand" to="/"><span className="brand-mark"><ScanFace size={22}/></span>proctor<span>ai</span></Link><div className="navlinks"><a href="#platform">Platform</a><a href="#privacy">Privacy</a><Link to="/login">Sign in</Link><Link className="btn btn-light" to="/register">Create account <ArrowUpRight size={15}/></Link></div></nav><section className="hero hero-editorial"><div className="hero-editorial-copy"><div className="eyebrow"><span className="pulse-dot"/> A FAIRER WAY TO ASSESS</div><h1>Online exams,<br/><em>with confidence.</em></h1><p className="hero-description">Thoughtful assessments with transparent, local-first proctoring. Give students a fair space to show what they know.</p><div className="hero-editorial-actions"><Link className="btn btn-dark" to="/register">Create your workspace <ArrowUpRight size={17}/></Link><Link className="btn btn-outline-dark" to="/login">Sign in <ChevronRight size={16}/></Link></div><div className="hero-trustline"><span><Check size={15}/>Local camera analysis</span><i/><span><Check size={15}/>Human-reviewed signals</span><i/><span><Check size={15}/>No continuous video</span></div></div><div className="hero-preview-wrap"><div className="preview-caption"><span>PRODUCT PREVIEW</span><span>STUDENT WORKSPACE</span></div><div className="hero-preview"><div className="preview-topbar"><span className="preview-brand"><i/><b>proctorai</b></span><span className="preview-local"><i/> LOCAL SESSION</span><span className="preview-avatar">S</span></div><div className="preview-layout"><aside className="preview-nav"><span className="preview-nav-active"><BookOpen size={13}/>Examinations</span><span><Activity size={13}/>My progress</span><span><ShieldCheck size={13}/>Privacy</span><div className="preview-nav-foot"><ShieldCheck size={14}/><span>Frames analysed locally</span></div></aside><main className="preview-main"><div className="preview-breadcrumb">MY ASSESSMENTS <span>›</span> CURRENT EXAM</div><div className="preview-title-row"><div><span className="preview-live-tag"><i/> IN PROGRESS</span><h2>Python Test</h2><p>Question 6 of 10 <span>·</span> 18 minutes remaining</p></div><div className="preview-timer"><Clock3 size={14}/>18:24</div></div><div className="preview-progress"><span/></div><div className="preview-question"><small>QUESTION 06</small><b>Which Python keyword defines a function?</b><div className="preview-option selected"><i>A</i> def <Check size={13}/></div><div className="preview-option"><i>B</i> function</div><div className="preview-option"><i>C</i> return</div></div><div className="preview-bottom"><span><ShieldCheck size={14}/>Camera frames are processed on this device</span><span>Answer saved <Check size={13}/></span></div></main></div></div><div className="preview-note"><span><ShieldCheck size={15}/></span><div><b>Privacy stays visible.</b><small>Students know what’s monitored and why.</small></div></div></div></section><section id="platform" className="features features-editorial"><div className="section-kicker">BUILT FOR BOTH SIDES OF THE EXAM</div><h2>Clear tools. Fairer assessments.</h2><p className="features-intro">Everything students and educators need to run an online assessment with confidence.</p><div className="feature-grid"><Feature icon={<ScanFace/>} title="Local by design" text="Camera frames are analysed on the student's device. With consent, one incident photo can be stored locally for review. Continuous video is never stored."/><Feature icon={<Brain/>} title="Explainable signals" text="Each proctoring event includes a clear reason. A risk score is a prompt for review, never a verdict."/><Feature icon={<ClipboardCheck/>} title="One connected workspace" text="Publish exams, follow active sessions, review events and return results in one place."/></div></section><section id="privacy" className="privacy-band"><div><div className="section-kicker">BUILT AROUND TRUST</div><h2>Technology should support judgment,<br/>not replace it.</h2><p>ProctorAI surfaces observable signals while leaving context and decisions to educators. Automated flags are reviewed by a person.</p></div><div className="privacy-stats"><div><ShieldCheck/><b>On-device</b><span>frame analysis</span></div><div><Users/><b>Human-led</b><span>event review</span></div><div><Activity/><b>Transparent</b><span>risk factors</span></div></div></section><footer><Link className="brand" to="/"><span className="brand-mark"><ScanFace size={20}/></span>proctor<span>ai</span></Link><span>Privacy-first assessment for a more confident classroom.</span><Link to="/login">Open your workspace <ArrowUpRight size={15}/></Link></footer></div>}
