function Login({onLogin}:any){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),nav=useNavigate();async function submit(e:any){e.preventDefault();setBusy(true);setError('');try{const {data}=await api.post('/auth/login',{email,password});saveSession(data.access_token,data.user);onLogin(data.user);nav('/app')}catch(err:any){setError(readableApiError(err,'Sign in failed. Check your email and password.'))}finally{setBusy(false)}}return <AuthFrame title="Welcome back" subtitle="Sign in to continue to your workspace"><form onSubmit={submit} className="auth-form"><label>Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@school.edu"/></label><label>Password<PasswordField value={password} onChange={(e:any)=>setPassword(e.target.value)} placeholder="Enter your password"/></label>{error&&<div className="error-box">{error}</div>}<button className="btn btn-primary full" disabled={busy}>{busy?'Signing in…':'Sign in'} <ArrowUpRight size={16}/></button></form><div className="demo-box"><b>Try the demo workspace</b><div><button onClick={()=>{setEmail(demo.student.email);setPassword(demo.student.password)}}>Fill student demo</button><button onClick={()=>{setEmail(demo.admin.email);setPassword(demo.admin.password)}}>Fill admin demo</button></div><small>Demo records are sample data and are labelled in the workspace.</small></div><p className="auth-switch">New to ProctorAI? <Link to="/register">Create an account</Link></p></AuthFrame>}
function Register({onLogin}:any){const [name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),nav=useNavigate();async function submit(e:any){e.preventDefault();try{const {data}=await api.post('/auth/register',{name,email,password});saveSession(data.access_token,data.user);onLogin(data.user);nav('/app')}catch(err:any){setError(readableApiError(err,'Registration failed. Check the details and try again.'))}}return <AuthFrame title="Create your account" subtitle="Set up your student profile to get started"><form onSubmit={submit} className="auth-form"><label>Full name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Your name"/></label><label>School email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@school.edu"/></label><label>Password<PasswordField value={password} minLength={10} onChange={(e:any)=>setPassword(e.target.value)} placeholder="At least 10 characters"/></label>{error&&<div className="error-box">{error}</div>}<button className="btn btn-primary full">Create student account <ArrowUpRight size={16}/></button></form><p className="auth-switch">Already registered? <Link to="/login">Sign in</Link></p></AuthFrame>}
