function RecentResults({results,admin=false}:any){return <section className="surface recent-results"><div className="surface-heading"><div><h2>Recent results</h2><p>Latest submitted examination outcomes.</p></div><Link to="/app/results">View all <ChevronRight size={15}/></Link></div><div className="recent-results-list">{results.map((r:any)=><div className="recent-result-row" key={r.id}>{admin&&<span className="profile-avatar">{(r.student||'S').slice(0,1)}</span>}<div className="recent-result-name"><b>{admin?r.student:r.exam_title}</b><small>{admin?r.exam:r.manual_review_required?'Awaiting written-answer review':'Submitted'}</small></div><strong>{r.score} / {r.max_score}</strong><span className={'status-pill '+(r.manual_review_required?'draft':'available')}>{r.manual_review_required?'Review pending':'Result ready'}</span></div>)}</div></section>}function ExamCard({exam}:any){return <article className="exam-card"><div className="exam-card-top"><span className="exam-symbol"><BookOpen size={18}/></span><span className="status-pill available">Available</span></div><h3>{exam.title}</h3><p>{exam.description}</p><div className="exam-meta"><span><Clock3 size={14}/>{exam.duration_minutes} min</span><span><ClipboardCheck size={14}/>{exam.questions.length} questions</span></div><Link className="exam-start" to={`/app/take/${exam.id}`}>View instructions <ArrowUpRight size={15}/></Link></article>}
function ExamList(){const [exams,setExams]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{let active=true;api.get('/student/exams').then(r=>{if(active){setExams(r.data);setError('')}}).catch(()=>{if(active)setError('Examinations could not load. Check your connection and try again.')}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[]);return <><PageTitle eyebrow="ASSESSMENTS" title="Examinations" subtitle="Browse available assessments and check their duration before starting."/>{error&&<div className="error-box" role="alert">{error}</div>}{loading?<div className="exam-grid wide">{[1,2,3].map(n=><div className="exam-card skeleton-card" key={n}><span/><span/><span/></div>)}</div>:<><div className="exam-grid wide">{exams.map(e=><ExamCard exam={e} key={e.id}/>)}</div>{!exams.length&&!error&&<div className="empty-state"><BookOpen/><h3>No published exams yet</h3><p>When an administrator publishes an assessment, it will appear here.</p></div>}</>}</>}
